CREATE TABLE IF NOT EXISTS schools (id VARCHAR(64) PRIMARY KEY, display_name VARCHAR(160) NOT NULL, settings_json JSON NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS school_memberships (id VARCHAR(64) PRIMARY KEY, school_id VARCHAR(64) NOT NULL, account_id VARCHAR(64) NOT NULL, role ENUM('admin','teacher') NOT NULL, display_label VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE CASCADE, UNIQUE KEY (school_id, account_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS classes (id VARCHAR(64) PRIMARY KEY, school_id VARCHAR(64) NOT NULL, display_name VARCHAR(120) NOT NULL, leaderboard_enabled TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE CASCADE, INDEX (school_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS class_memberships (id VARCHAR(64) PRIMARY KEY, class_id VARCHAR(64) NOT NULL, child_id VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE, FOREIGN KEY (child_id) REFERENCES children(id) ON DELETE CASCADE, UNIQUE KEY (class_id, child_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS curriculum_skills (id VARCHAR(64) PRIMARY KEY, framework VARCHAR(80) NOT NULL, grade_band VARCHAR(32) NOT NULL, subject_id VARCHAR(64) NOT NULL, label VARCHAR(160) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mission_assignments (id VARCHAR(64) PRIMARY KEY, class_id VARCHAR(64) NOT NULL, mission_id VARCHAR(32) NOT NULL, skill_id VARCHAR(64), assigned_by_membership_id VARCHAR(64) NOT NULL, due_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE, FOREIGN KEY (skill_id) REFERENCES curriculum_skills(id), FOREIGN KEY (assigned_by_membership_id) REFERENCES school_memberships(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_mastery (id VARCHAR(64) PRIMARY KEY, child_id VARCHAR(64) NOT NULL, skill_id VARCHAR(64) NOT NULL, evidence_count INT NOT NULL DEFAULT 0, correct_count INT NOT NULL DEFAULT 0, mastery_percent INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (child_id) REFERENCES children(id) ON DELETE CASCADE, FOREIGN KEY (skill_id) REFERENCES curriculum_skills(id), UNIQUE KEY (child_id, skill_id)) ENGINE=InnoDB;
